import io
import uu


def encode(data, name='file'):
    out = io.BytesIO()
    uu.encode(io.BytesIO(data), out, name, 0o644)
    return out.getvalue()

import binascii


def encode(data, name='file'):
    lines = [b'begin 644 ' + name.encode() + b'\n']
    for i in range(0, len(data), 45):
        lines.append(binascii.b2a_uu(data[i:i + 45]))
    lines.append(b' \nend\n')
    return b''.join(lines)
